mapper.select:

WHERE e.deleted = 0
  AND e.tenant_id = #{spec.tenantId}

  AND 1 = 0




      OR e.id IN

        #{employeeId}



      OR e.dept_id IN

        #{departmentId}



      OR e.position_id IN

        #{positionId}



      OR EXISTS (
        SELECT 1
        FROM iam_user u
        INNER JOIN iam_user_role ur ON ur.user_id = u.id AND ur.deleted = 0
        WHERE u.employee_id = e.id
          AND u.deleted = 0
          AND u.tenant_id = e.tenant_id
          AND ur.role_id IN

            #{roleId}

      )



ORDER BY e.id ASC
